INSERT INTO directory_entries (agency_name, category, jurisdiction_state, official_url, contact_details, summary_rule, last_verified_date, is_active, is_proposed_pending_gazette) VALUES
  ($seed$LHDN / HASiL — Inland Revenue Board (Stamp Duty)$seed$, $seed$STAMP_DUTY_TAX$seed$, $seed$NATIONAL$seed$, $seed$https://www.hasil.gov.my$seed$, $seed$HASiL Care Line (see official site)$seed$, $seed$Assesses stamp duty on the MOT (Borang 14A) and loan agreement. Duty is charged on the higher of price or market value; under-declaration can be re-assessed with penalties.$seed$, NULL, true, false),
  ($seed$STAMPS — e-Duti Setem portal (LHDN)$seed$, $seed$STAMP_DUTY_TAX$seed$, $seed$NATIONAL$seed$, $seed$https://stamps.hasil.gov.my$seed$, $seed$Via HASiL$seed$, $seed$Online stamping & adjudication. Your lawyer submits MOT and loan instruments here; keep the stamp certificate.$seed$, NULL, true, false),
  ($seed$Rule: MOT stamp duty scale (citizens & PRs)$seed$, $seed$STAMP_DUTY_TAX$seed$, $seed$NATIONAL$seed$, $seed$https://www.hasil.gov.my$seed$, $seed$$seed$, $seed$1% first RM100,000; 2% RM100,001–500,000; 3% RM500,001–1,000,000; 4% above RM1,000,000 — on the higher of price or market value.$seed$, NULL, true, false),
  ($seed$Rule: Non-citizen flat duty on residential transfers$seed$, $seed$STAMP_DUTY_TAX$seed$, $seed$NATIONAL$seed$, $seed$https://www.hasil.gov.my$seed$, $seed$$seed$, $seed$8% flat on residential property transferred to non-citizens (excluding PRs) from 1 Jan 2026, on the higher of consideration or market value.$seed$, NULL, true, false),
  ($seed$Rule: Loan agreement stamp duty$seed$, $seed$STAMP_DUTY_TAX$seed$, $seed$NATIONAL$seed$, $seed$https://www.hasil.gov.my$seed$, $seed$$seed$, $seed$0.5% flat of the financing principal (RM5 per RM1,000 or part thereof), unless exempt.$seed$, NULL, true, false),
  ($seed$Rule: First-time Malaysian homebuyer exemption (current)$seed$, $seed$STAMP_DUTY_TAX$seed$, $seed$NATIONAL$seed$, $seed$https://www.hasil.gov.my$seed$, $seed$$seed$, $seed$100% MOT and loan-agreement duty exemption for first residential home up to RM500,000, SPAs executed up to 31 Dec 2027. Never owned any residential property (incl. inherited, gifted or jointly owned). Not for vacant/agricultural land.$seed$, NULL, true, false),
  ($seed$Budget 2027 PROPOSAL: First-home stamp duty relief$seed$, $seed$STAMP_DUTY_TAX$seed$, $seed$NATIONAL$seed$, $seed$https://www.mof.gov.my$seed$, $seed$$seed$, $seed$PROPOSED for SPAs 1 Jan 2027 – 31 Dec 2030: full relief up to RM500,000 and 50% relief for RM500,001–RM750,000. NOT LAW until gazetted — confirm with your lawyer.$seed$, NULL, true, true),
  ($seed$Rule: RPGT retention by purchaser$seed$, $seed$STAMP_DUTY_TAX$seed$, $seed$NATIONAL$seed$, $seed$https://www.hasil.gov.my$seed$, $seed$$seed$, $seed$Purchaser retains 3% of the price (may differ for some sellers) and remits to LHDN within 60 days of disposal. Your lawyer usually handles this from the balance price.$seed$, NULL, true, false),
  ($seed$JPPH — Valuation & Property Services Department$seed$, $seed$VALUATION$seed$, $seed$NATIONAL$seed$, $seed$https://www.jpph.gov.my$seed$, $seed$State JPPH branch offices$seed$, $seed$Provides market-value opinions used by LHDN for stamp duty adjudication. A large gap between declared price and JPPH value triggers re-assessment.$seed$, NULL, true, false),
  ($seed$NAPIC — National Property Information Centre$seed$, $seed$VALUATION$seed$, $seed$NATIONAL$seed$, $seed$https://napic.jpph.gov.my$seed$, $seed$$seed$, $seed$Official transaction data — use it to sense-check the asking price before making an offer.$seed$, NULL, true, false),
  ($seed$LPPEH — Board of Valuers, Appraisers, Estate Agents & Property Managers$seed$, $seed$VALUATION$seed$, $seed$NATIONAL$seed$, $seed$https://www.lppeh.gov.my$seed$, $seed$$seed$, $seed$Check that any valuer you hire is registered. Unregistered 'agents' cannot lawfully charge agency fees.$seed$, NULL, true, false),
  ($seed$JKPTG — Department of Director General of Lands and Mines$seed$, $seed$LAND_OFFICE$seed$, $seed$NATIONAL$seed$, $seed$https://www.jkptg.gov.my$seed$, $seed$Links to every state PTG$seed$, $seed$National Land Code administration. Use it to find your state's Land & Mines Office (PTG) and district land office (PDT) for title searches and registration.$seed$, NULL, true, false),
  ($seed$PTG Selangor — Land & Mines Office$seed$, $seed$LAND_OFFICE$seed$, $seed$SELANGOR$seed$, $seed$https://ptg.selangor.gov.my$seed$, $seed$$seed$, $seed$Official title search (Carian Rasmi), registration of MOT, state consent for restricted titles in Selangor.$seed$, NULL, true, false),
  ($seed$PTG Wilayah Persekutuan$seed$, $seed$LAND_OFFICE$seed$, $seed$WP_KUALA_LUMPUR$seed$, $seed$https://ptgwp.gov.my$seed$, $seed$$seed$, $seed$Title searches, transfer registration and consents for Federal Territories land.$seed$, NULL, true, false),
  ($seed$JUPEM — Department of Survey and Mapping$seed$, $seed$SURVEY_PLANNING$seed$, $seed$NATIONAL$seed$, $seed$https://www.jupem.gov.my$seed$, $seed$$seed$, $seed$Certified survey plans show boundaries and road reserves — essential to confirm legal access for land purchases.$seed$, NULL, true, false),
  ($seed$PLANMalaysia — Town & Country Planning$seed$, $seed$SURVEY_PLANNING$seed$, $seed$NATIONAL$seed$, $seed$https://www.planmalaysia.gov.my$seed$, $seed$$seed$, $seed$Local and structure plans show zoning. Check that the intended use matches before buying land.$seed$, NULL, true, false),
  ($seed$Malaysian Bar — find a conveyancing lawyer$seed$, $seed$LEGAL_PROFESSIONAL$seed$, $seed$NATIONAL$seed$, $seed$https://www.malaysianbar.org.my$seed$, $seed$$seed$, $seed$Verify your lawyer holds a valid practising certificate. Legal fees follow the Solicitors' Remuneration Order 2023 scale plus 8% SST.$seed$, NULL, true, false),
  ($seed$Rule: Solicitors' Remuneration Order 2023 (scale fee)$seed$, $seed$LEGAL_PROFESSIONAL$seed$, $seed$NATIONAL$seed$, $seed$https://www.malaysianbar.org.my$seed$, $seed$$seed$, $seed$1.25% on first RM500,000 (min RM500); 1% on next RM7,000,000; above RM7.5m negotiable up to 1%. Same scale applies to loan documentation. Discounts only as allowed by Bar Council rulings.$seed$, NULL, true, false),
  ($seed$Bank Negara Malaysia — BNMLINK$seed$, $seed$FINANCING$seed$, $seed$NATIONAL$seed$, $seed$https://www.bnm.gov.my$seed$, $seed$BNMLINK contact centre$seed$, $seed$Consumer guidance on housing loans and complaints against banks. Banks lend on the lower of price and valuation.$seed$, NULL, true, false),
  ($seed$KPKT — Ministry of Local Government Development$seed$, $seed$LOCAL_COUNCIL_UTILITIES$seed$, $seed$NATIONAL$seed$, $seed$https://www.kpkt.gov.my$seed$, $seed$$seed$, $seed$Local councils (PBT) under KPKT collect assessment tax and approve building plans — check for unapproved extensions and arrears.$seed$, NULL, true, false),
  ($seed$TNB — electricity account transfer$seed$, $seed$LOCAL_COUNCIL_UTILITIES$seed$, $seed$NATIONAL$seed$, $seed$https://www.tnb.com.my$seed$, $seed$$seed$, $seed$At vacant possession, record the meter reading and transfer the account; confirm no arrears.$seed$, NULL, true, false),
  ($seed$Air Selangor — water account transfer$seed$, $seed$LOCAL_COUNCIL_UTILITIES$seed$, $seed$SELANGOR$seed$, $seed$https://www.airselangor.com$seed$, $seed$$seed$, $seed$Transfer the water account at handover; obtain final bill from seller.$seed$, NULL, true, false),
  ($seed$Laws of Malaysia — National Land Code, Stamp Act, RPGT Act$seed$, $seed$LEGISLATION$seed$, $seed$NATIONAL$seed$, $seed$https://lom.agc.gov.my$seed$, $seed$Attorney General's Chambers$seed$, $seed$Primary sources for the National Land Code 2020 (Revised), Stamp Act 1949 and RPGT Act 1976.$seed$, NULL, true, false)
